@Test
public void setServerTimestampForNonCqlNativeStatements() throws RequestValidationException, RequestExecutionException {
    String createKsCQL = "CREATE KEYSPACE non_native_ts_test" + " WITH REPLICATION = { 'class' : 'SimpleStrategy', 'replication_factor' : 1 };";
    String createTableCQL = "CREATE TABLE non_native_ts_test.table_0 (k int PRIMARY KEY, v int)";
    String insertCQL = "INSERT INTO non_native_ts_test.table_0 (k, v) values (1, ?)";
    String selectCQL = "SELECT v, writetime(v) AS wt FROM non_native_ts_test.table_0 WHERE k = 1";
    QueryProcessor.instance.process(createKsCQL, QueryState.forInternalCalls(), QueryOptions.forInternalCalls(Collections.<ByteBuffer>emptyList()));
    QueryProcessor.instance.process(createTableCQL, QueryState.forInternalCalls(), QueryOptions.forInternalCalls(Collections.<ByteBuffer>emptyList()));
    QueryProcessor.instance.process(insertCQL, QueryState.forInternalCalls(), QueryOptions.forInternalCalls(ConsistencyLevel.ONE, Arrays.asList(ByteBufferUtil.bytes(2))));
    UntypedResultSet.Row row = QueryProcessor.instance.executeInternal(selectCQL).one();
    assertEquals(2, row.getInt("v"));
    long timestamp1 = row.getLong("wt");
    assertFalse(timestamp1 == -1l);
    // per CASSANDRA-8246 the two updates will have the same (incorrect)
    // timestamp, so reconcilliation is by value and the "older" update wins
    QueryProcessor.instance.process(insertCQL, QueryState.forInternalCalls(), QueryOptions.forInternalCalls(ConsistencyLevel.ONE, Arrays.asList(ByteBufferUtil.bytes(1))));
    row = QueryProcessor.executeInternal(selectCQL).one();
    assertEquals(1, row.getInt("v"));
    assertTrue(row.getLong("wt") > timestamp1);
}

@Test
public void testInvalidatePreparedStatementsOnDrop() {
    String createTableStatement = "CREATE TABLE IF NOT EXISTS " + KEYSPACE + ".qp_cleanup (id int PRIMARY KEY, cid int, val text);";
    String dropTableStatement = "DROP TABLE IF EXISTS " + KEYSPACE + ".qp_cleanup;";
    session.execute(createTableStatement);
    PreparedStatement prepared = session.prepare("INSERT INTO " + KEYSPACE + ".qp_cleanup (id, cid, val) VALUES (?, ?, ?)");
    PreparedStatement preparedBatch = session.prepare("BEGIN BATCH " + "INSERT INTO " + KEYSPACE + ".qp_cleanup (id, cid, val) VALUES (?, ?, ?);" + "APPLY BATCH;");
    session.execute(dropTableStatement);
    session.execute(createTableStatement);
    session.execute(prepared.bind(1, 1, "value"));
    session.execute(preparedBatch.bind(2, 2, "value2"));
    session.execute(dropKsStatement);
    session.execute(createKsStatement);
    session.execute(createTableStatement);
    // The driver will get a response about the prepared statement being invalid, causing it to transparently
    // re-prepare the statement.  We'll rely on the fact that we get no errors while executing this to show that
    // the statements have been invalidated.
    session.execute(prepared.bind(1, 1, "value"));
    session.execute(preparedBatch.bind(2, 2, "value2"));
    session.execute(dropKsStatement);
}

@Test
public void testStatementRePreparationOnReconnect() {
    session.execute(dropKsStatement);
    session.execute(createKsStatement);
    session.execute("CREATE TABLE IF NOT EXISTS " + KEYSPACE + ".qp_test (id int PRIMARY KEY, cid int, val text);");
    String insertCQL = "INSERT INTO " + KEYSPACE + ".qp_test (id, cid, val) VALUES (?, ?, ?)";
    String selectCQL = "Select * from " + KEYSPACE + ".qp_test where id = ?";
    PreparedStatement preparedInsert = session.prepare(insertCQL);
    PreparedStatement preparedSelect = session.prepare(selectCQL);
    session.execute(preparedInsert.bind(1, 1, "value"));
    assertEquals(1, session.execute(preparedSelect.bind(1)).all().size());
    cluster.close();
    cluster = Cluster.builder().addContactPoint("127.0.0.1").withPort(DatabaseDescriptor.getNativeTransportPort()).build();
    session = cluster.connect();
    preparedInsert = session.prepare(insertCQL);
    preparedSelect = session.prepare(selectCQL);
    session.execute(preparedInsert.bind(1, 1, "value"));
    assertEquals(1, session.execute(preparedSelect.bind(1)).all().size());
}

