    assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, list(map(1, 1, 2, 2), map(5, 5, 6, 6))));
    execute("DELETE l[0] FROM %s WHERE k = 1");
    assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, list(map(5, 5, 6, 6))));
}

