    assertRows(execute("SELECT k, v FROM %s WHERE k = 0 AND m CONTAINS 1"), row(0, 0), row(0, 1));
    assertRows(execute("SELECT k, v FROM %s WHERE m CONTAINS 2"), row(0, 1));
    assertEmpty(execute("SELECT k, v FROM %s  WHERE m CONTAINS 4"));
