@Test
public void testTimeuuid() throws Throwable {
    createTable("CREATE TABLE %s (k int, t timeuuid, PRIMARY KEY(k, t))");
    assertInvalidThrow(SyntaxException.class, "INSERT INTO %s (k, t) VALUES (0, 2012-11-07 18:18:22-0800)");
