    // this setup should generate the following row (assuming indexes are of 4Kb each):
    // [colA, colB, colC, colD, colE, colF, colG, colH, colI]
    // indexed as:
    // index0 [colA, colC]
    // index1 [colD, colF]
    // index2 [colG, colI]
