    bytes.put((byte) 0);
    bytes.rewind();
    try {
        int c = comparator.compare(uuid, bytes);
        assert c == 1 : "Expecting bytes to sort before uuid, but got " + c;
    } catch (Exception e) {
        fail("Shouldn't throw exception");
    }
}

