        val = test.type.compare(buf.name(), buf2.name());
        assert test.type.compare(nat.name(), nat2.name()) == val;
        assert test.type.compare(nat.name(), buf2.name()) == val;
        assert test.type.compare(buf.name(), nat2.name()) == val;
        // test CounterCell
