    assert (source.equals(TimeSerializer.instance.toString(time)));
    source = "00:00:00.000012311";
    time = TimeSerializer.timeStringToLong(source);
    assert (source.equals(TimeSerializer.instance.toString(time)));
    source = "00:00:00.123000000";
    time = TimeSerializer.timeStringToLong(source);
    assert (source.equals(TimeSerializer.instance.toString(time)));
    source = "00:00:12.123450000";
    time = TimeSerializer.timeStringToLong(source);
