@Test
public void testParsing() {
    CassandraVersion version;
    version = new CassandraVersion("1.2.3");
    assert version.major == 1 && version.minor == 2 && version.patch == 3;
    version = new CassandraVersion("1.2.3-foo.2+Bar");
